    {
      "symbol": "⚡",
      "tooltip": "Operational circuit breakers physically cut power to contain cascading system failures before catastrophe spreads."
    },
    {
      "symbol": "⚖️",
      "tooltip": "Strict design defect liability shifts the burden of unconstrained system harms directly onto the manufacturer's balance sheet."
    }
  ],
