    {
      "symbol": "⚖️",
      "tooltip": "Strict joint liability places financial accountability on upstream capital rather than shifting legal burdens onto downstream startups."
    },
    {
      "symbol": "🔌",
      "tooltip": "Treating base AI models as raw utility engines strips away the illusion of technical compliance shields."
    }
  ],
